{
  "metadata": {
    "default": null,
    "keys": [
      "remediation_advice",
      "references"
    ]
  },
  "content": [
    {
      "id": "vrt-1",
      "references": [
        "https://example.com/reference1",
        "https://example.com/reference2"
      ],
      "remediation_advice": "Patch the vulnerability."
