                  "additionalProperties": false
                }
              },
              "eliminated": {
                "type": "array",
                "items": {
                  "type": "integer"
                }
              }
            }
          }
        }
      },
      "required": [
        "winner"
      ],
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "dependencies": {
    "isTest": [
      "results",
      "tiebreak",
      "counts"
    ]
  }
